import { parse } from './src/opentype.mjs';
import fs from 'fs';
const read=f=>fs.readFileSync('test/fonts/'+f);
function renameTag(buf, from, to){ const b=Buffer.from(buf); const n=b.readUInt16BE(4); for(let i=0;i<n;i++){const p=12+i*16; if(b.toString('latin1',p,p+4)===from){b.write(to.padEnd(4,' '),p); return true;}} return false; }
const cases=[['TestGVAROne.ttf','fvar'],['TestAVAR.ttf','fvar'],['TestCVARGVAROne.ttf','cvt '],['TestCVARGVAROne.ttf','fvar'],['TestHVAROne.otf','fvar'],['Changa-VariableFont_wght.ttf','fvar']];
for(const [file,tag] of cases){
  const b=renameTag(read(file),tag,'ZZZZ');
  const warns=[]; const ow=console.warn; console.warn=(...a)=>warns.push(a.join(' '));
  try{ const f=parse(b); console.warn=ow; console.log(file,'remove',JSON.stringify(tag),'OK warns=',JSON.stringify(warns)); }
  catch(e){ console.warn=ow; console.log(file,'remove',JSON.stringify(tag),'ERR',e.constructor.name,e.message,'warns=',JSON.stringify(warns)); }
}
""}

