});

describe('parsing TrueType fonts', () => {
    test('parses the sfnt header and core metrics tables', () => {
        const font = parse(readFont('Changa-Regular.ttf'));

        expect(font).toBeInstanceOf(opentype.Font);
        expect(font.outlinesFormat).toBe('truetype');
        expect(font.unitsPerEm).toBe(1000);
        expect(font.ascender).toBe(1227);
