export function u8(n) { return [n & 0xff]; }
export function u16(n) { return [(n >> 8) & 0xff, n & 0xff]; }
export function u32(n) { return [(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff]; }
export function op(n) { return n < 1200 ? [n] : [12, n - 1200]; }
export function operand(n) { return [29, (n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff]; }
export function cffIndex(items) {
    if (items.length === 0) return [0, 0];
    let offset = 1;
    const offsets = [1];
    const body = [];
    for (const item of items) {
        const bytes = Array.from(item);
        offsets.push(offset + bytes.length);
        offset += bytes.length;
        body.push(...bytes);
    }
    const out = [...u16(items.length), 1];
    out.push(...offsets);
    out.push(...body);
    return out;
}

// Generic CFF1 builder.
// options: fontNames (array of strings), topDicts (array of fn(offsets)->bytes),
// sections: ordered [{name, bytes}], header prefix overrides
export function buildCff1(options) {
    const fontNames = options.fontNames || ['TestFont'];
    const topDicts = options.topDicts || [];
    const sections = options.sections || [];
    const nameIndexLen = cffIndex(fontNames.map((s) => Array.from(s, (c) => c.charCodeAt(0)))).length;
    const stringIndex = options.stringIndex || cffIndex([]);
    const gsubrIndex = options.gsubrIndex || cffIndex([]);
    const emptyTopDict = topDicts.map((f) => f({}));
    const topDictIndexLen = cffIndex(emptyTopDict).length;
    const header = options.header || [1, 0, 4, 4];
    const prefixLen = header.length + nameIndexLen + topDictIndexLen + stringIndex.length + gsubrIndex.length;
    const offsets = {};
    let pos = prefixLen;
    for (const section of sections) {
        offsets[section.name] = pos;
        pos += section.bytes.length;
    }
    const dicts = topDicts.map((f) => f(offsets));
    const out = [
        ...header,
        ...cffIndex(fontNames.map((s) => Array.from(s, (c) => c.charCodeAt(0)))),
        ...cffIndex(dicts),
        ...stringIndex,
        ...gsubrIndex
    ];
    for (const section of sections) out.push(...section.bytes);
    return new DataView(Uint8Array.from(out).buffer);
}

export function simpleCharString(dx, dy) {
    return [139 + dx, 139 + dy, 21, 14];
